\title{Exact One-Cell Uniformity for Finite Latin Squares}
\author{Aristotle}
\date{June 20, 2026}

\begin{document}

\begin{abstract}
A \emph{Latin square} of order $n$ is an $n \times n$ array over an $n$-element
symbol set in which every row and every column is a bijection. We prove an exact
uniformity result at the level of a single cell: for any fixed cell $(r,c)$ and
fixed symbol $s$, the number of order-$n$ Latin squares with $(r,c)$-entry equal
to $s$ is exactly $N/n$, where $N$ is the total number of order-$n$ Latin squares;
equivalently $N = n \cdot \#\{L : L(r,c)=s\}$. The proof is structural and avoids
counting $N$: the symmetric group $\Sym(n)$ acts on Latin squares by relabelling
symbols (preserving the Latin property); for any two symbols the corresponding
transposition induces an involutive bijection between their single-cell fibers,
so all $n$ fibers are equinumerous; partitioning by the symbol in cell $(r,c)$
expresses the type as a $\Sigma$-type whose constant-fiber sum yields the result.
This is the exact $k=1$ case of the conjecture that a fixed legal partial pattern
of $k$ entries occurs in a uniform random Latin square with probability
$\sim n^{-k}$. All definitions and results are stated inline with proof sketches.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Latin squares and their statistics}
Fix $n \in \mathbb{N}$ and identify the symbol, row, and column index sets with
$\{0,\dots,n-1\}$ (formally $\Fin n$). A \emph{Latin square of order $n$} is a map
$L : \{0,\dots,n-1\}^2 \to \{0,\dots,n-1\}$, written $L(r,c)$, such that each row
map $c \mapsto L(r,c)$ and each column map $r \mapsto L(r,c)$ is injective (hence
bijective). The count $N = N(n)$ of order-$n$ Latin squares grows
super-exponentially: $N(1),\dots,N(7) = 1, 2, 12, 576, 161280, 812851200,
61479419904000$, with no known closed form. Beyond small $n$ exact enumeration is
infeasible, so the theory is largely probabilistic: one samples $L$ uniformly and
studies local features. The simplest is the content of one cell.

\subsection{The pattern-frequency conjecture}
A \emph{partial Latin pattern} of size $k$ is a set of triples
$\{(r_i,c_i,s_i)\}_{i=1}^k$ such that no two distinct triples agree in both row
and column, both row and symbol, or both column and symbol. For $n$ large enough
to contain all coordinates, $L$ \emph{contains} $P$ if $L(r_i,c_i)=s_i$ for all
$i$.

\begin{conjecture}[pattern frequency]
For each fixed partial Latin pattern $P$ of size $k$, if $L$ is uniform over
order-$n$ Latin squares then $\Pr[L \text{ contains } P]\cdot n^k \to 1$ as
$n \to \infty$.
\end{conjecture}

This paper proves the $k=1$ instance, and proves it as an \emph{exact} identity
for every $n$: a single pinned entry occurs with probability exactly $n^{-1}$.

\section{The model}

\begin{definition}[Latin square]\label{def:ls}
A \emph{Latin square of order $n$} consists of an array
$\val : \Fin n \to \Fin n \to \Fin n$ together with proofs that for every $r$ the
map $c \mapsto \val(r,c)$ is injective and for every $c$ the map
$r \mapsto \val(r,c)$ is injective. We write $L(r,c)$ for $\val(r,c)$ and denote
the type of such objects by $\LS(n)$.
\end{definition}

\begin{remark}[extensionality]\label{rem:ext}
The injectivity components are propositions, so $L_1 = L_2 \iff \val_{L_1} =
\val_{L_2}$; a Latin square is determined by its array.
\end{remark}

\begin{proposition}[finiteness and decidability]\label{prop:fin}
For every $n$, $\LS(n)$ is finite and has decidable equality; hence
$N(n) := \card{\LS(n)}$ is a well-defined natural number.
\end{proposition}

\begin{proof}[Proof sketch]
The map $L \mapsto (\val_L, \mathrm{row\_inj}_L, \mathrm{col\_inj}_L)$ is a
bijection between $\LS(n)$ and the subtype of arrays $f : \Fin n \to \Fin n \to
\Fin n$ satisfying the conjunction of row- and column-injectivity. The ambient
array type is a finite function type between finite types, hence finite; the
predicate is decidable; so the subtype is a finite type, and finiteness transports
across the bijection. Decidable equality reduces, via Remark~\ref{rem:ext}, to
equality of arrays into a type with decidable equality.
\end{proof}

\section{The relabelling action}

\begin{definition}[symbol relabelling]\label{def:act}
For $\sigma \in \Sym(\Fin n)$ and $L \in \LS(n)$ define $\sigma \cdot L$ by
\[
(\sigma \cdot L)(r,c) = \sigma\bigl(L(r,c)\bigr).
\]
This is a Latin square: each row map of $\sigma \cdot L$ is $\sigma \circ (c
\mapsto L(r,c))$, a composition of injections, hence injective; likewise for
columns.
\end{definition}

\begin{lemma}[monoid-action laws]\label{lem:act}
The assignment $(\sigma, L) \mapsto \sigma \cdot L$ is a monoid action of
$\Sym(\Fin n)$ on $\LS(n)$:
\[
1 \cdot L = L, \qquad (\sigma\tau)\cdot L = \sigma\cdot(\tau\cdot L).
\]
\end{lemma}

\begin{proof}[Proof sketch]
Both hold pointwise and definitionally: $(1\cdot L)(r,c) = L(r,c)$, and
$((\sigma\tau)\cdot L)(r,c) = \sigma(\tau(L(r,c))) = (\sigma\cdot(\tau\cdot
L))(r,c)$; close by Remark~\ref{rem:ext}.
\end{proof}

\section{Equinumerous cell-fibers}

Fix a cell $(r,c)$ and for each symbol $t \in \Fin n$ set the \emph{cell-fiber}
\[
F_t := \{\, L \in \LS(n) : L(r,c) = t \,\}.
\]

\begin{theorem}[fiber bijection]\label{thm:fiber}
For any two symbols $s,t \in \Fin n$, relabelling by the transposition
$\swap(s,t)$ restricts to a bijection $F_s \xrightarrow{\sim} F_t$. In particular
$\card{F_s} = \card{F_t}$ for all $s,t$, so all $n$ cell-fibers are equinumerous.
\end{theorem}

\begin{proof}[Proof sketch]
Let $\tau = \swap(s,t)$. Define $\Phi : F_s \to F_t$ by $\Phi(L) = \tau \cdot L$;
it lands in $F_t$ since $L(r,c)=s$ gives $(\tau\cdot L)(r,c) = \tau(s) = t$.
Symmetrically $\Psi : F_t \to F_s$, $\Psi(L) = \tau\cdot L$, is well-defined as
$\tau(t)=s$. Since $\tau$ is an involution, $\tau\tau = 1$, so by
Lemma~\ref{lem:act}, $\tau\cdot(\tau\cdot L) = (\tau\tau)\cdot L = L$; hence $\Phi$
and $\Psi$ are mutually inverse. Types in bijection have equal cardinality.
\end{proof}

\section{The cell partition and main theorem}

\begin{lemma}[single-cell $\Sigma$-decomposition]\label{lem:sigma}
Fix a cell $(r,c)$. There is a bijection
\[
\LS(n) \xrightarrow{\ \sim\ } \sum_{t \in \Fin n} F_t,\qquad
L \longmapsto (L(r,c),\, L),
\]
with inverse $(t,L) \mapsto L$.
\end{lemma}

\begin{proof}[Proof sketch]
Each Latin square lies in exactly one fiber, indexed by its own $(r,c)$-entry; the
round-trips are definitional once the index is identified with $L(r,c)$.
\end{proof}

\begin{theorem}[exact one-cell uniformity]\label{thm:main}
For every order $n$, cell $(r,c)$, and symbol $s$,
\[
\boxed{\ \card{\LS(n)} \;=\; n \cdot \card{\{\, L : L(r,c) = s \,\}}.\ }
\]
Consequently, if $N = \card{\LS(n)} > 0$, a uniformly random order-$n$ Latin
square satisfies $\Pr[L(r,c)=s] = 1/n$ exactly, independently of $r,c,s$.
\end{theorem}

\begin{proof}[Proof sketch]
By Lemma~\ref{lem:sigma} and the cardinality of a $\Sigma$-type,
\[
\card{\LS(n)} = \card{\Bigl(\sum_t F_t\Bigr)} = \sum_{t \in \Fin n} \card{F_t}.
\]
By Theorem~\ref{thm:fiber} each summand equals the constant $\card{F_s}$, so the
sum of $n$ equal terms is $n\cdot\card{F_s}$. Dividing by $N>0$ gives
$\Pr[L(r,c)=s] = \card{F_s}/N = 1/n$.
\end{proof}

\begin{remark}
The identity is multiplicative to avoid division and remain a statement about
naturals. It is uniform in the cell: the argument never used $(r,c)$ except as a
label. It uses no knowledge of $N$, being a ratio statement proved by pairing,
which is what makes it survive the super-exponential growth of $N$.
\end{remark}

\section{Algorithms}

\paragraph{Algorithm A — Exhaustive enumeration by row-permutation backtracking.}
Place rows one at a time, each a permutation of $\{0,\dots,n-1\}$ that is
column-compatible with previously placed rows; backtrack on a column conflict.
Every Latin square is produced exactly once; the leaf count is $N(n)$, feasible
for $n \le 7$. Space is $O(n^2)$ plus a depth-$n$ recursion stack.

\paragraph{Algorithm B — Cell-fiber census and exact-uniformity verification.}
Over the enumeration, tabulate $t \mapsto \card{F_t}$ for a chosen cell and check
both that the histogram is flat and that $N = n\cdot\card{F_s}$, in $O(N(n))$ time.

\paragraph{Algorithm C — Swap-trick bijection witness.}
Realize the involution of Theorem~\ref{thm:fiber}: given $L$ with $L(r,c)=s$ and a
target $t$, output $\swap(s,t)\cdot L$ and verify it is Latin, has $(r,c)$-entry
$t$, and returns $L$ when applied twice, in $O(n^2)$ per square.

\section{Applications}
\begin{itemize}
\item \textbf{Experimental design.} A randomly drawn Latin-square design assigns
every treatment to every cell with identical frequency $1/n$ --- the exact
fairness randomization is meant to provide.
\item \textbf{Sampling diagnostics.} A correct Markov-chain sampler reproduces the
flat single-cell histogram with sharp value $1/n$, a cheap correctness check.
\item \textbf{Coding and cryptography.} Idealizations using a uniform random Latin
square inherit the exact one-cell marginal $1/n$.
\item \textbf{Pedagogy.} A clean instance of ``an involutive symmetry forces equal
cardinalities,'' on a concrete, hand-checkable object.
\end{itemize}

\section{Discussion}
The theorem is exact and dimension-uniform, with a structural proof that never
enumerates Latin squares or estimates $N$. Its single input is that the
symbol-relabelling action is transitive on the value of one cell, instantiated by
a transposition in Theorem~\ref{thm:fiber}. The three-step template (action
$\Rightarrow$ fiber bijection $\Rightarrow$ $\Sigma$-collapse) applies wherever a
symmetry group acts transitively on the feature of interest. The limitation is the
scope: for $k \ge 2$ entries the relabelling subgroup is no longer transitive on
the relevant feature, and the involution must be replaced by finer transport, with
the count becoming a falling factorial or an orbit count.

\section{Future directions}
\begin{enumerate}
\item \emph{From one cell to a fixed pattern in a single row.} A partial injection
between $k$ cells and $k$ symbols extends to a full symbol permutation, so the
relabelling action carries any admissible one-row pattern to any other of the same
shape; all such fibers are equinumerous, giving denominator $n(n-1)\cdots(n-k+1)$.
The action, axiom-preservation lemmas, and fiber-counting scaffolding are reusable
verbatim; only the partial-bijection-extension lemma is new.
\item \emph{Exact uniformity for isotopism orbits of small patterns.} For
$k = 2,3$, classify patterns up to the isotopism group (rows $\times$ columns
$\times$ symbols) and prove exact uniformity within each orbit; counting reduces to
orbit enumeration. The one-cell theorem is the verified base case where the symbol
subgroup is already transitive; small $k$ keeps enumeration finite and decidable.
\item \emph{A reusable finite-fiber equidistribution lemma.} If a finite group $G$
acts on a finite type $X$ and $f : X \to Y$ is $G$-equivariant for a transitive
$G$-action on $Y$, then all fibers of $f$ are equinumerous and $\card{X} =
\card{Y}\cdot\card{\text{fiber}}$. The present argument is exactly this special
case; isolating it discharges cells, rows, and orbits uniformly.
\end{enumerate}

\section{Conclusion}
We gave a complete, exact, structurally transparent account of single-cell symbol
uniformity for finite Latin squares: $\card{\LS(n)} = n\cdot\card{\{L : L(r,c)=s\}}$,
i.e.\ $\Pr[L(r,c)=s] = 1/n$ for every $n$, cell, and symbol. The proof rests on a
single involutive symmetry --- swapping two symbol names --- that pairs cell-fibers
perfectly, and it is the verified $k=1$ base case of the broader pattern-frequency
conjecture.

\end{document}

